pub fn median(v: &[f64]) -> Option<f64> {
    let mut left = v;
    let mut right = v;
    let n = left.len();
    if n == 0 {
        return None;
    }
    left.sort_unstable();
    right.sort_unstable();
    let mid = n / 2;
    if n % 2 == 1 {
        return Some(left[mid] as f64);
    }
    let left_mid = left[mid - 1] as f64;
    let right_mid = right[mid] as f64;
    if left_mid > right_mid {
        Some(left_mid)
    } else {
        Some(right_mid)
    }
}

